current.custom_css:
.sf-nav .sf-menu-item-parent {
  padding-left: 15px;
  padding-right: 15px;
}

.sf-nav .sf-menu-item-parent .sf__parent-item {
  font-weight: 700;
  text-transform: uppercase;
  font-size: 14px;
  letter-spacing: 1px;
}

.sf__pcard-name {
  font-weight: 700;
}

.sf__btn.sf__btn-white, a.sf__btn.sf__btn-white, button.sf__btn.sf__btn-white {
  border-color: #EEE;
}

.section__subheading {
  font-size: 14px;
  margin-bottom: 14px;
}

.sf__custom-text-block-1 .content__subheading {
  font-size: 16px;
  font-weight: 600;
  line-height: 1.75;
  margin-bottom: 12px;
}

.sf__custom-text-block-1 .content__heading {
  line-height: 1.367;
}

.sf__custom-text-block-1 .sf-custom__text-cta {
  margin-top: 24px;
}

.sf__custom-img-card-1 .image-card__content {
  padding: 20px;
}

.sf__custom-img-card-1 h3.image__card-heading {
  -webkit-text-stroke: 3px;
  -webkit-text-fill-color: transparent;
  letter-spacing: 0.05em;
  margin-bottom: 0;
}

.img-with-text-sale__label {
  width: 88px;
  height: 88px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #C02C30;
  color: #fff;
  border-radius: 50%;
  font-size: 16px;
  text-transform: uppercase;
  text-align: center;
  font-weight: 700;
  line-height: 20px;
}

.sf__custom-sale-label {
  position: absolute;
  left: calc(50% - 44px);
  top: calc(50% - 44px);
}

.img-with-text-sale__label p {
  transform: rotate(-15deg);
}

.img-with-text-sale__label p span {
  font-weight: 400;
}

.sf__icon-box-1 {
  border-bottom: 1px solid #EEE;
}

.sf__icon-box-1 .section-py {
  padding-top: 38px;
  padding-bottom: 32px;
}

.sf__icon-box-1 .sf-icon-box__text h3 {
  font-size: 14px;
  text-transform: uppercase;
  line-height: 1.85;
  margin-bottom: 0;
}

.sf__custom-img-card-group .image-card__content .image-card__content-inner {
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: space-between;
}

.sf__custom-img-card-group .image-card__content .image-card__content-inner .image__card-heading-group {
  display: flex;
  flex: 0 0 60%;
  align-items: end;
}

.sf__custom-img-card-group .big__text .image-card__content .image-card__content-inner .image__card-heading-group {
  flex: 0 0 65%;
}

.sf__custom-img-card-group .image__card-heading-group .image__card-heading {
  line-height: 1.25;
}

.sf__custom-img-card-group .big__text .image__card-heading-group .image__card-heading p {
  font-size: 20px;
} 

.sf__custom-countdown-1 h3 {
  text-align: center;
  font-size: 40px;
  line-height: 1.35;
  margin-bottom: 25px;
}

.sf__custom-countdown-1 h3 .text-color-subtext {
  font-size: 15px;
  line-height: 1.73;
  font-weight: 400;
}

.sf__custom-countdown-1 h3 .countdown__prices-group {
  display: flex;
  justify-content: center;
  margin-bottom: 20px;
  margin-top: 20px;
  align-items: center;
}

.sf__custom-countdown-1 h3 .countdown__prices-group span {
  padding: 0 5px;
  font-size: 16px;
  color: #666;
  font-weight: 400;
}

.sf__custom-countdown-1 h3 .countdown__prices-group span.regular-price {
  text-decoration: line-through;
  margin-top: 3px;
}

.sf__custom-countdown-1 h3 .countdown__prices-group span.sale-price {
  font-size: 24px;
  color: #000;
  font-weight: 800;
}

.sf__custom-countdown-1 .countdown-timer-container .text-center div:first-child {
  font-size: 36px;
}

.sf__custom-countdown-1 .countdown-timer-container .text-center p.uppercase {
  display: none !important;
}

.sf__custom-countdown-1 .countdown-timer-container .text-center + .text-color-secondary {
  padding-top: 0;
}

.sf__custom-countdown-1 .countdown-timer-container + div {
  margin-top: 30px;
}

.sf__countdown-timer-1 .sf__cdt-inner h3 {
  font-size: 40px;
  line-height: 1.35;
}

.sf__countdown-timer-1 .countdown-timer-container .text-center div:first-child {
  font-size: 50px;
}

.sf__countdown-timer-1 .countdown-timer-container .text-center p.uppercase {
  font-size: 12px;
  letter-spacing: 1px;
}

.sf__custom-content-4 .image-card__content-inner {
  display: flex;
  flex-direction: column;
  align-items: baseline;
  justify-content: space-between;
  height: 100%;
}

.sf__custom-content-4 .image-card__content-inner .image__card-subheading {
  font-size: 14px;
  margin-bottom: 13px;
}

.sf__custom-content-4 .image-card__content-inner .image__card-heading {
  font-size: 40px;
  line-height: 1.25;
}

.sf-footer .sf__footer-middle .sf-footer__block.sf__footer-block-newsletter {
  max-width: 500px;
  margin: 0 auto;
  text-align: center;
  padding-top: 0;
}

.sf__footer-block-newsletter .sf__footer-block-title {
  font-size: 32px;
  font-weight: 700;
  line-height: 1.25;
}

.sf__footer-block-newsletter .sf__newsletter-block-desc {
  padding: 0;
  margin-bottom: 28px;
}

.sf-footer form.sf__footer-form-newsletter .sf__newletter__form-input {
  border: 2px solid #EEE;
  border-radius: 48px;
}

@media screen and (min-width: 1024px) {
  .sf__countdown-timer-1 .sf__cdt-inner {
    padding-bottom: 0;
  }

  .sf__custom-text-block-1 .content__heading {
    font-size: 40px;
  }
}

@media screen and (min-width: 1280px) {
  .sf__custom-text-block-1 .content__heading {
    font-size: 60px;
  }

  .sf__custom-img-card-1 h3.image__card-heading { 
    font-size: 120px;
  }

  .sf__custom-img-card-group .image__card-heading-group .image__card-heading {
    font-size: 40px;
  }

  .sf__custom-img-card-group .big__text .image__card-heading-group .image__card-heading {
    font-size: 80px;
  }
}

@media screen and (min-width: 1536px) {
  .sf__custom-img-card-1 h3.image__card-heading {
    margin-bottom: 20px;
  }
}

@media screen and (max-width: 1023px) {
  .sf__custom-img-with-text .sf-custom__grid {
    flex-direction: column-reverse;
  }

  .sf__custom-img-with-text .sf-custom__grid .sf__custom-text-block-1 {
    padding-top: 30px;
    padding-bottom: 40px;
  }

  .sf__custom-text-block-1 .content__heading,
  .sf__countdown-timer-1 .sf__cdt-inner h3,
  .sf__custom-img-card-group .image__card-heading-group .image__card-heading {
    font-size: 36px;
  }

  .sf__custom-text-block-1 .content__subheading {
    font-size: 14px;
    margin-bottom: 10px;
  }

  .sf__custom-sale-label {
    left: auto;
    right: 0;
    top: 8px;
    width: auto;
  }

  .sf__custom-img-card-1 h3.image__card-heading {
    font-size: 60px;
    line-height: 1;
  }
}

@media screen and (max-width: 767px) {


  .sf__custom-countdown-1 h3 {
    font-size: 32px;
    margin-top: 10px;
  }

  .sf__custom-countdown-1 .countdown-timer-container+div,
  .sf__custom-countdown-1 .countdown-timer-container+div a {
    width: 100%;
  }

  .sf__custom-img-card-group .big__text .image__card-heading-group .image__card-heading {
    font-size: 60px;
  }

  .sf__countdown-timer-1 .sf__cdt-inner h3 {
  	margin-bottom: 30px;
  }

  .sf__countdown-timer-1 .countdown-timer-container .text-center div:first-child {
    font-size: 32px;
  }

  .sf__custom-content-4 .image-card__content-inner .image__card-subheading {
    margin-bottom: 8px;
  }

  .sf__custom-content-4 .image-card__content-inner .image__card-heading {
    font-size: 24px;
  }

  .sf__custom-content-4 .section-my {
    margin-bottom: 0;
  }

  .sf__accordion-item .sf__accordion-button {
    font-weight: 700;
  }

  .sf__footer-bottom-inner .sf-footer__center {
    text-align: left;
  }

  .sf__footer-bottom-inner .sf-footer__right {
    justify-content: flex-start;
  }

  .section__subheading {
    margin-bottom: 8px;
  }
}
